    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib, a piperazine-containing oral kinase inhibitor, has 98% absolute oral bioavailability, demonstrating that piperazine and heteroaromatic features are compatible with excellent absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Niraparib, a basic heteroaromatic drug, had approximately 73% absolute oral bioavailability in fasted patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Risdiplam, a fused heteroaromatic drug with a basic amine, has high oral bioavailability due to complete absorption and low first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence from structurally related oral drugs reports absolute F values well above 20% (46–98%), and no affirmative low-F evidence is present. The physicochemical prior is overridden by these direct measurements, so the query is predicted high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the exact query molecule.",
    "All evidence analogues have Morgan similarity below 0.4, limiting structural transferability.",
    "No query-specific permeability, efflux, or first-pass metabolism data are available.",
    "The low neutral fraction and high TPSA remain physicochemical concerns, though similar high-F drugs share these features."
  ],
